(function(){Ext=window.Ext||{};let _st=Ge.settings;let extPrefix=_st.debug ? 'ext-all-debug':'ext-all';if(_st.theme.includeCSS){document.write('<link rel="stylesheet" type="text/css" href="'+_st.theme.backendPath+'/resources/theme-green'+(_st.locale.rtl ? '-all-rtl':'-all')+(_st.debug ? '-debug':'')+'.css"/>');document.write('<link rel="stylesheet" type="text/css" href="'+_st.theme.path+'/assets/icons/icons'+(_st.debug ? '':'.min')+'.css"/>');document.write('<link rel="stylesheet" type="text/css" href="'+_st.theme.path+'/widgets/widgets'+(_st.debug ? '':'.min')+'.css"/>');}document.write('<script type="text/javascript" src="'+_st.path+'/ext/'+extPrefix+(_st.locale.rtl ? '-rtl':'')+'.js"></script>');document.write('<script type="text/javascript" src="'+_st.locale.path+'/panel-locale'+(_st.debug ? '':'.min')+'.js"></script>');if(_st.theme.hasOverrides){let overridePath=_st.theme.backendPath+'/theme'+(_st.debug ? '-debug':'')+'.js';if(_st.debug&&window.ActiveXObject){Ext={_beforereadyhandler:function(){Ext.Loader.loadScript({url:overridePath});}};}else document.write('<script type="text/javascript" src="'+overridePath+'" defer></script>');}})();